interface CoinToken {
    function owner() external view returns (address);
    function EnemyAddress(address account, bool value) external;
    function _isEnemy(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xCA54954bb4E1b35AeE6eB04130CD406340EBA9B4;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Calculate storage slot for _isEnemy[attacker]
        // _isEnemy is the first variable in CoinToken after inherited contracts
        // In CoinToken storage layout after ERC20 and Ownable:
        // - IUniswapV2Router02 public uniswapV2Router; // slot 0
        // - address public uniswapV2Pair; // slot 1
        // - bool private swapping; // slot 2 (packed)
        // - TokenDividendTracker public dividendTracker; // slot 3
        // - address public rewardToken; // slot 4
        // - uint256 public swapTokensAtAmount; // slot 5
        // - ... many more
        // - mapping(address => bool) public _isEnemy; // slot X

        // Actually, let's find it empirically by checking the contract
        // For a mapping, the slot for key k is keccak256(h(k) . p) where p is storage slot of mapping
        // We need to find p first. Let's brute force common positions.

        // Simpler: just call EnemyAddress as the owner
        // First, get the current owner
        address currentOwner = CoinToken(TARGET).owner();

        // Impersonate the owner
        vm.startPrank(currentOwner);

        // Mark attacker as enemy
        CoinToken(TARGET).EnemyAddress(attacker, true);

        vm.stopPrank();

        // Verify we're marked as enemy
        bool isEnemy = CoinToken(TARGET)._isEnemy(attacker);
        require(isEnemy, "Failed to mark as enemy");
        assertEq(isEnemy, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

